require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/auth.php';
$q=trim($_GET['q']??'');$st=$pdo->prepare("SELECT s.*,c.name customer FROM sales s LEFT JOIN customers c ON c.id=s.customer_id WHERE s.invoice_no LIKE ? OR COALESCE(c.name,'Walk-in') LIKE ? ORDER BY s.id DESC");$st->execute(["%$q%","%$q%"]);$rows=$st->fetchAll();$page_title='Sales';require __DIR__.'/../partials/header.php';?>
<div class="d-flex justify-content-between mb-3"><div><h3 class="fw-bold">Sales</h3><p class="text-muted">Sales history and invoices.</p></div><a class="btn btn-primary" href="pos.php">New Sale</a></div>
<div class="card p-3"><form class="d-flex gap-2 mb-3"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Invoice or customer"><button class="btn btn-outline-secondary">Search</button></form><div class="table-responsive"><table class="table"><thead><tr><th>Invoice</th><th>Customer</th><th>Subtotal</th><th>Total</th><th>Payment</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a href="view.php?id=<?=$r['id']?>"><?=e($r['invoice_no'])?></a></td><td><?=e($r['customer']??'Walk-in')?></td><td>$<?=money($r['subtotal'])?></td><td class="fw-bold">$<?=money($r['total'])?></td><td><?=e(ucfirst($r['payment_method']))?></td><td><?=e($r['sale_date'])?></td></tr><?php endforeach;?></tbody></table></div></div>
